import {suggestMapping} from './import-tools.js';
import {businessKinds,renderBusiness,businessFields,businessPayload,reportHTML,lifecycleLabels} from './crm-ui.js';
import {normaliseSenders,normaliseLists,eligibleContacts} from './mailketing.js';
let S, page=location.hash.slice(1)||'dashboard',credit=null,search='',filterStatus='',filterTag='',offset=0;
const selectedContacts=new Set();
const filteredContacts=()=>S.contacts.filter(c=>JSON.stringify([c.name,c.email,c.phone]).toLowerCase().includes(search.toLowerCase())&&(!filterStatus||c.status===filterStatus)&&(!filterTag||c.tags.includes(filterTag)));
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>t?new Date(t).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}):'—',num=n=>Number(n||0).toLocaleString('id-ID'),badge=s=>`<span class="badge ${e(s)}">${e(s)}</span>`;
async function api(path,data,method){const r=await fetch('/api/'+path,{method:method||(data?'POST':'GET'),headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});const d=await r.json();if(r.status===401){login();throw Error(d.error);}if(!r.ok)throw Error(d.error||'Request gagal');return d;}
const toast=t=>{let el=document.querySelector('#toast');el.textContent=t;el.style.display='block';setTimeout(()=>el.style.display='none',5000);};
function action(fn){return async ev=>{const button=ev?.currentTarget;if(button?.tagName==='BUTTON')button.disabled=true;try{await fn();}catch(err){toast(err.message);}finally{if(button?.tagName==='BUTTON')button.disabled=false;}};}
function login(){app.innerHTML=`<form class="login card" id="login"><div class="brand"><span>✉</span>MailK CRM<small>EMAIL MARKETING SUITE</small></div><h1>Masuk ke workspace</h1><p class="muted">Kelola kontak dan email dari satu tempat.</p><label>Email admin</label><input name="email" type="email" required autocomplete="username"><label>Password</label><input name="password" type="password" required autocomplete="current-password"><button class="primary" style="width:100%;margin-top:22px">Masuk →</button><p id="error"></p></form>`;document.querySelector('#login').onsubmit=async ev=>{ev.preventDefault();try{await api('login',Object.fromEntries(new FormData(ev.target)));await load();}catch(err){document.querySelector('#error').textContent=err.message;}};}
async function load(){S=await api('state');const live=new Set(S.contacts.map(c=>c.id));for(const id of selectedContacts)if(!live.has(id))selectedContacts.delete(id);render();}
const nav=[['dashboard','◈ Dashboard'],['group','CONTACTS'],['contacts','Semua Kontak'],['tags','Tags'],['fields','Custom Fields'],['segments','Segments'],['import','Import CSV'],['group','CRM PELANGGAN'],['deals','Pipeline Penjualan'],['tasks','Tugas & Follow-up'],['orders','Transaksi'],['notes','Catatan Interaksi'],['tickets','Keluhan & Pelayanan'],['reports','Laporan CRM'],['syncstatus','Status Sinkronisasi'],['group','EMAIL MESSAGING'],['templates','Template Email'],['campaigns','Campaigns'],['schedule','Schedule Campaign'],['responders','Autoresponder'],['logs','Riwayat Email'],['group','WORKSPACE'],['automations','⚡ Automation'],['integrations','⌘ Integrasi Mailketing'],['settings','⚙ Pengaturan']];
const titles=Object.fromEntries(nav);
const btn=(text,id,cl='')=>`<button class="${cl}" data-act="${id}">${text}</button>`;
const head=(title,sub,act='')=>`<div class="row"><div><h1>${title}</h1><span class="muted">${sub}</span></div><div class="actions">${act}</div></div>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty">Belum ada data. Tambahkan item pertama Anda.</td></tr>`}</tbody></table></div>`;
const checks=(name,items,selected=[])=>`<div class="checklist">${items.map(t=>`<label><input type="checkbox" name="${name}" value="${e(t.id)}" ${selected.includes(t.id)?'checked':''}> ${e(t.name)}</label>`).join('')||'<span class="muted">Belum ada item.</span>'}</div>`;
const options=(items,v='')=>items.map(t=>`<option value="${e(t.id)}" ${t.id===v?'selected':''}>${e(t.name)}</option>`).join('');
function render(){if(!S)return;if(!nav.some(([k])=>k===page))page='dashboard';app.innerHTML=`<aside><div class="brand"><span>✉</span>${e(S.config.name)}<small>EMAIL MARKETING SUITE</small></div><nav>${nav.map(([k,v])=>k==='group'?`<div class="group">${v}</div>`:`<button data-page="${k}" class="${page===k?'selected':''}">${v}</button>`).join('')}</nav><p class="muted" style="margin:30px 12px;font-size:11px">Self-hosted · v0.4.1<br>Workspace pribadi Anda</p></aside><main><header><div>${btn('☰','menu','mobile-menu')} <b>${e(titles[page]||'Dashboard')}</b></div><div class="actions header-actions">${badge(S.config.enabled?'Pengiriman aktif':'Pengiriman dijeda')}${btn('✉ '+(credit===null?'Cek kredit':num(credit)),'credits')} ${btn('Keluar','logout')}</div></header><div class="content" id="content"></div></main>`;
const C=document.querySelector('#content');const H={e,head,btn,table,badge,date,field,options};
if(businessKinds.includes(page)){C.innerHTML=renderBusiness(S,page,H);}
else if(page==='reports'){C.innerHTML=head('Laporan CRM','Gunakan transaksi dan aktivitas nyata untuk menilai hubungan pelanggan.')+`<form id="report-filter" class="toolbar"><div><label>Dari (WIB)</label><input name="from" type="date" value="${new Date(Date.now()-2592000000).toISOString().slice(0,10)}" required></div><div><label>Sampai (WIB)</label><input name="to" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><button class="primary">Tampilkan</button></form><div id="report-result"></div>`;}
else if(page==='syncstatus'){C.innerHTML=head('Status Sinkronisasi','Antrean kontak keluar dan webhook masuk.',btn('Refresh','reload'))+`<div id="sync-result"></div>`;}
else if(page==='dashboard'){
 const accepted=S.metrics.accepted,opens=S.metrics.opened;
 C.innerHTML=`<div class="hero"><div><h1>Selamat datang di ${e(S.config.name)}</h1><p>Semua aktivitas email marketing Anda dalam satu tempat.</p>${badge(S.config.enabled?'Pengiriman aktif':'Pengiriman dijeda')}</div><div class="credits">${credit===null?'—':num(credit)}<small>KREDIT MAILKETING</small></div></div>${!S.contacts.length?`<div class="getting-started card"><div><span class="eyebrow">MULAI DI SINI</span><h2>Siapkan campaign pertama Anda</h2><p class="muted">Hubungkan pengirim, tambahkan kontak, lalu kirim satu email test.</p></div><div class="actions"><button data-page="integrations">1 · Hubungkan Mailketing</button>${btn('2 · Tambah kontak','new:contacts','primary')}${btn('3 · Buat template','new:templates')}</div></div>`:''}<div class="grid">${[['♙','TOTAL CONTACTS',S.contacts.length],['✓','ACTIVE',S.contacts.filter(x=>x.status==='active').length],['⊘','UNSUBSCRIBED',S.contacts.filter(x=>x.status==='unsubscribed').length],['＋','BARU (7 HARI)',S.contacts.filter(x=>x.created>Date.now()-604800000).length],['✉','DITERIMA PROVIDER',accepted],['◉','OPENED (UNIK)',opens],['↗','OPEN RATE',accepted?(100*opens/accepted).toFixed(1)+'%':'—'],['◷','ANTREAN',S.metrics.queued]].map(([i,l,n])=>`<div class="card"><span class="icon">${i}</span><small class="muted">${l}</small><div class="metric">${typeof n==='number'?num(n):n}</div></div>`).join('')}</div><div class="grid three">${[['Campaigns',S.campaigns.length,'campaigns'],['Schedule Campaign',S.campaigns.filter(c=>c.status==='scheduled').length,'schedule'],['Autoresponder',S.responders.filter(r=>r.active).length,'responders']].map(([n,v,k])=>`<div class="card"><h2>${n}</h2><div class="metric">${v}</div><p class="muted">${k==='responders'?'Alur aktif':'Total'}</p><button class="primary" data-page="${k}">Kelola ${n} →</button></div>`).join('')}</div><div class="grid three"><div class="card"><h2>Aktivitas email terakhir</h2>${S.events.slice(0,7).map(x=>`<p>${badge(x.type)} ${e(S.contacts.find(c=>c.id===x.contact)?.name||'Kontak')}<br><small class="muted">${date(x.created)}</small></p>`).join('')||'<p class="muted">Aktivitas akan muncul di sini.</p>'}</div><div class="card"><h2>Top Tags</h2>${S.tags.map(t=>({...t,n:S.contacts.filter(c=>c.tags.includes(t.id)).length})).sort((a,b)=>b.n-a.n).slice(0,5).map(t=>`<div>${e(t.name)} <b style="float:right">${num(t.n)}</b><div class="tagbar"><div style="width:${S.contacts.length?t.n/S.contacts.length*100:0}%"></div></div></div>`).join('')||'<p class="muted">Tambahkan tag untuk segmentasi.</p>'}</div><div class="card"><h2>Aksi cepat</h2><p><button data-page="import">↑ Import contacts</button></p><p>${btn('＋ Buat campaign','new:campaigns','primary')}</p><p><button data-page="settings">⚙ Pengaturan pengirim</button></p></div></div><p class="muted">Log menampilkan 500 job dan 200 event terakhir. Metrik ringkasan menggunakan keseluruhan data. Open tracking dapat dipengaruhi pemblokiran gambar dan pemindai email.</p>`;
}else if(page==='contacts'){
 const cs=filteredContacts();
 offset=Math.min(offset,Math.max(0,Math.floor((cs.length-1)/50)*50));C.innerHTML=head('Semua Kontak',`${num(cs.length)} kontak`,btn('＋ Add Contact','new:contacts','primary')+btn('Export CSV','export'))+(S.contacts.length?'':`<div class="onboarding card"><span class="icon">♙</span><h2>Mulai dari kontak pertama Anda</h2><p class="muted">Kontak di Mailketing tidak otomatis disalin ke CRM ini. Tambahkan kontak sendiri atau import CSV, lalu sinkronkan ke list Mailketing.</p><div class="actions">${btn('＋ Tambah kontak','new:contacts','primary')}<button data-page="import">↑ Import CSV</button></div></div>`)+`<div class="toolbar"><input id="search" placeholder="Cari nama, email, phone…" value="${e(search)}"><select id="tagFilter"><option value="">Semua tags</option>${options(S.tags,filterTag)}</select><select id="statusFilter"><option value="">Semua status</option>${['active','pending','unsubscribed','bounced'].map(s=>`<option ${s===filterStatus?'selected':''}>${s}</option>`).join('')}</select>${btn('Filter','filter')}</div>`+`<div class="toolbar selection-toolbar"><strong id="selection-count"></strong>${btn('Pilih semua hasil filter ('+num(cs.length)+')','select-filter')}${btn('Batalkan pilihan','clear-selection')}${btn('Tambah tag','bulk-tag')}${btn('Sinkronkan pilihan','bulk-sync')}${btn('Hapus pilihan','bulk-delete','danger')}<small class="muted">Centang judul tabel untuk memilih halaman ini (maks. 50 kontak). Pilihan tersimpan saat pindah halaman.</small></div>`+table(['<input type="checkbox" id="select-page" aria-label="Pilih semua kontak di halaman ini">','Nama','Email','Phone','Tags','Status','Ditambahkan','Aksi'],cs.slice(offset,offset+50).map(c=>`<tr><td><input type="checkbox" data-contact-select="${c.id}" aria-label="Pilih ${e(c.email)}" ${selectedContacts.has(c.id)?'checked':''}></td><td><b>${e(c.name||'—')}</b><br><small class="muted">${e(lifecycleLabels[c.lifecycle||'lead'])}${c.company?' · '+e(c.company):''}</small></td><td>${e(c.email)}</td><td>${e(c.phone||'—')}</td><td>${c.tags.map(id=>badge(S.tags.find(t=>t.id===id)?.name||id.slice(0,6))).join('')}</td><td>${badge(c.status)}</td><td>${date(c.created)}</td><td class="actions">${btn('Detail','history:'+c.id)+btn('Edit','edit:contacts:'+c.id)+(c.status==='pending'?btn('Verifikasi consent','activate:'+c.id):'')}${btn('Hapus','del:contacts:'+c.id,'danger')}</td></tr>`))+`<div class="pagination">${btn('←','prev')} ${cs.length?offset+1:0}–${Math.min(offset+50,cs.length)} / ${cs.length} ${btn('→','next')}</div>`;
}else if(['tags','fields','segments','templates','responders','automations'].includes(page)){
 const k=page;C.innerHTML=head(titles[k],'Kelola '+titles[k].toLowerCase(),btn('＋ Tambah','new:'+k,'primary'));
 if(k==='segments')C.innerHTML+=`<div class="grid three">${S[k].map(s=>`<div class="card"><div class="row"><h2>${e(s.name)}</h2><div class="metric">${s.count}</div></div><p>${s.rules.map(r=>badge(`${({tag:'Tag',status:'Status',name:'Nama',email:'Email',opened:'Pernah membuka',clicked:'Pernah klik'}[r.field]||r.field.replace('custom.',''))} ${{is:'=',contains:'memiliki',not:'≠'}[r.op]||r.op} ${r.field==='tag'?(S.tags.find(t=>t.id===r.value)?.name||'Tag dihapus'):r.value}`)).join('')}</p><p class="muted">${s.mode==='any'?'Salah satu':'Semua'} aturan harus terpenuhi</p><div class="actions">${btn('Edit',`edit:${k}:${s.id}`)}${btn('Export',`segment-export:${s.id}`)}${btn('Hapus',`del:${k}:${s.id}`,'danger')}</div></div>`).join('')||'<p class="empty">Belum ada segmen.</p>'}</div>`;
 else C.innerHTML+=table(['Nama','Detail','Status / Jumlah','Aksi'],S[k].map(d=>`<tr><td><b>${e(d.name)}</b></td><td>${k==='tags'?`<span class="badge" style="color:${e(d.color)}">● ${e(d.color)}</span>`:k==='fields'?`${e(d.key)} · ${e(d.type)}`:k==='templates'?date(d.updated):k==='responders'?`${e(S.tags.find(t=>t.id===d.tag)?.name)} · ${d.steps.length} steps`:`${e(d.trigger)} → ${e(d.action)} · ${d.delay} menit`}</td><td>${k==='tags'?S.contacts.filter(c=>c.tags.includes(d.id)).length:k==='fields'?(d.required?'Wajib':'Opsional'):k==='templates'?'HTML + block editor':badge(d.active?'active':'paused')}</td><td class="actions">${['responders','automations'].includes(k)?btn(d.active?'Pause':'Aktifkan',`toggle:${k}:${d.id}`):''}${btn('Edit',`edit:${k}:${d.id}`)}${k==='templates'?btn('Preview',`preview:${d.id}`)+btn('Send test',`test:${d.id}`):''}${btn('Hapus',`del:${k}:${d.id}`,'danger')}</td></tr>`));
}else if(['campaigns','schedule'].includes(page)){
 C.innerHTML=head(page==='schedule'?'Schedule Campaign':'Campaigns','Jadwal ditampilkan dalam WIB (UTC+7).',btn('＋ Buat campaign','new:campaigns','primary'))+table(['Nama / Subject','Jadwal','Status','Penerima','Aksi'],S.campaigns.filter(c=>page!=='schedule'||c.send_at).map(c=>`<tr><td><b>${e(c.name)}</b><br>${e(c.subject)}</td><td>${date(c.send_at)}</td><td>${badge(c.status)}</td><td>${c.recipients||'—'}</td><td class="actions">${['draft','scheduled'].includes(c.status)?btn('Edit','edit:campaigns:'+c.id)+btn('Kirim sekarang','launch:'+c.id,'primary'):''}${['running','scheduled'].includes(c.status)?btn('Batalkan','cancel:'+c.id,'danger'):''}</td></tr>`));
}else if(page==='logs'){
 C.innerHTML=head('Email Log','Accepted berarti diterima provider; status inbox perlu verifikasi provider.',btn('Refresh','reload'))+table(['Kontak','Campaign / Flow','Status','Waktu','Error','Aksi'],S.jobs.map(j=>`<tr><td>${e(S.contacts.find(c=>c.id===j.contact)?.email||'Kontak dihapus')}</td><td>${e(S.campaigns.find(c=>c.id===j.campaign)?.name||S.responders.find(c=>c.id===j.owner)?.name||S.automations.find(c=>c.id===j.owner)?.name||'Test email')}</td><td>${badge(j.status)}</td><td>${date(j.due)}</td><td style="max-width:260px;white-space:normal">${e(j.error)}</td><td>${['failed','uncertain'].includes(j.status)?btn('Retry','retry:'+j.id):''}</td></tr>`));
}else if(page==='import')C.innerHTML=head('Import from CSV','Upload → mapping field → tags → import')+`<div class="card"><div class="steps"><span>1 Upload</span><span>2 Map fields</span><span>3 Tags</span><span>4 Import</span></div><div class="dropzone"><h2>Upload daftar kontak Anda</h2><p class="muted">CSV dengan header · koma atau titik koma · maksimal 10 MB / 10.000 baris</p><input type="file" id="csv" accept=".csv,.txt"></div><div id="mapping"></div></div><div class="card"><h2>Riwayat import</h2><button data-act="import-history">Lihat 30 batch terakhir</button><div id="import-history"></div></div>`;
else if(page==='integrations')C.innerHTML=head('Integrasi Mailketing','Sambungkan kontak dan kirim email melalui akun Mailketing Anda.')+`<div class="connection-banner"><div><span class="connection-dot ${S.config.connected?'ready':''}"></span><b>${S.config.connected?'Token Mailketing tersedia':'Hubungkan akun Mailketing'}</b><p>${S.config.connected?'Klik cek koneksi untuk memverifikasi akses akun.':'Pasang MAILKETING_API_TOKEN di environment aplikasi Coolify.'}</p></div>${btn('Cek koneksi & kredit','credits','primary')}</div><div class="setup-path"><span>1 · Verifikasi koneksi</span><span>2 · Pilih pengirim</span><span>3 · Tambahkan kontak</span><span>4 · Sinkronkan list</span></div><div class="grid two"><div class="card integration-card"><div class="row"><div><span class="icon">✉</span><b>Akun & pengirim</b></div>${badge(S.config.connected?'Token tersedia':'Belum diatur')}</div><p class="muted">Lihat alamat pengirim terverifikasi dan pilih yang akan digunakan untuk email.</p><div class="account-summary"><span>Pengirim saat ini</span><strong>${e(S.config.from_email||'Belum dipilih')}</strong><span>Kredit email</span><strong>${credit===null?'Belum diperiksa':num(credit)}</strong></div><div class="actions">${btn('Pilih pengirim','senders')}${btn('Lihat list','lists')}${btn('Sinkronkan kontak →','sync','primary')}</div></div><div class="card integration-card"><div class="row"><div><span class="icon purple">↔</span><b>Webhook & aktivitas</b></div>${badge(S.config.webhook_url?'URL tersedia':'Belum diatur')}</div><p class="muted">Mailketing memberi tahu CRM saat kontak baru masuk, email bounce, atau penerima berhenti berlangganan.</p><div class="webhook-box"><span>Alamat webhook aplikasi</span><div class="actions">${btn('Salin URL webhook','copy-webhook')}${btn('Lihat URL','show-webhook')}</div><code id="webhook-display" hidden></code></div><p class="muted small">Gunakan URL yang sama untuk New Subscriber, Bounce, dan Unsubscribe. Open/click dilacak melalui email aplikasi.</p></div></div><div class="card"><div class="row"><div><h2>Kontak CRM & list Mailketing</h2><span class="muted">Kontak aktif dengan persetujuan siap disinkronkan.</span></div><button data-page="contacts">Kelola kontak →</button></div><div class="mini-metrics"><div><strong>${num(S.contacts.length)}</strong><span>Total kontak CRM</span></div><div><strong>${num(eligibleContacts(S.contacts).length)}</strong><span>Siap disinkronkan</span></div><div><strong>${num(S.contacts.filter(c=>c.mailketing_lists?.length).length)}</strong><span>Terhubung ke list</span></div></div>${S.contacts.length?'':'<div class="notice">Belum ada kontak CRM. Tambahkan kontak atau import CSV terlebih dahulu; daftar subscriber Mailketing yang sudah ada belum diimpor otomatis.</div>'}</div><details class="card api-details"><summary>Integrasi untuk pengembang · API kontak CRM</summary><p class="muted">Untuk form atau aplikasi lain. ${S.config.api_configured?'Token CRM tersedia.':'Opsional; belum ada token CRM.'}</p><pre>Header: Authorization: Bearer CRM_API_TOKEN

POST /api/add-contact
{"email":"pelanggan@example.com","name":"Pelanggan","consent":true,"tags":[],"custom":{}}

POST /api/tag-contact
{"email":"pelanggan@example.com","tag":"ID_TAG","untag":"ID_TAG_LAMA"}

GET /api/contact?email=pelanggan@example.com
POST /api/remove-contact
{"email":"pelanggan@example.com"}</pre><p class="muted">Sumber eksternal memerlukan adapter/webhook ke endpoint CRM.</p></details>`;
else if(page==='settings')C.innerHTML=head('Settings','Identitas workspace dan pengiriman email.')+`<form class="card" id="settings"><div class="form-grid">${[['name','Nama workspace'],['from_name','Nama pengirim'],['from_email','Email pengirim (domain terverifikasi)'],['address','Alamat bisnis / footer']].map(([k,l])=>`<div><label>${l}</label><input name="${k}" value="${e(S.config[k])}" ${k==='from_email'?'type="email"':''} required></div>`).join('')}</div><label><input type="checkbox" name="enabled" ${S.config.enabled?'checked':''}> Aktifkan pengiriman email</label><p class="notice">Sebelum mengaktifkan: verifikasi domain pengirim di Mailketing dan pastikan APP_URL menggunakan domain HTTPS yang benar.</p><button class="primary">Simpan pengaturan</button></form><div class="grid two"><div class="card"><h2>Keamanan</h2><p>Password admin dan API token hanya dikonfigurasi di environment server.</p><p>Session 12 jam · cookie HttpOnly · pembatasan login · pemeriksaan origin.</p></div><div class="card"><h2>Audit aktivitas</h2>${S.audit.slice(0,8).map(a=>`<p>${e(a.action)}<br><small class="muted">${date(a.created)}</small></p>`).join('')||'<p class="muted">Belum ada aktivitas.</p>'}</div></div>`;
if(page==='dashboard'){const overdue=S.tasks.filter(t=>t.status==='open'&&t.due<Date.now());C.innerHTML+=`<div class="grid two"><div class="card"><div class="row"><h2>Prioritas follow-up</h2><button data-page="tasks">Lihat tugas →</button></div>${overdue.length?overdue.slice(0,5).map(t=>`<p><b>${e(t.name)}</b> ${badge('Terlambat')}<br><small class="muted">${e(S.contacts.find(c=>c.id===t.contact)?.name||'Kontak')} · ${date(t.due)}</small></p>`).join(''):'<p class="muted">Tidak ada tugas terlambat.</p>'}</div><div class="card"><div class="row"><h2>Hubungan pelanggan</h2><button data-page="reports">Laporan CRM →</button></div><div class="mini-metrics"><div><strong>${S.deals.filter(d=>!['won','lost'].includes(d.stage)).length}</strong><span>Peluang aktif</span></div><div><strong>${S.tickets.filter(t=>t.status!=='resolved').length}</strong><span>Keluhan terbuka</span></div><div><strong>${S.contacts.filter(c=>c.lifecycle==='customer').length}</strong><span>Pelanggan</span></div></div></div></div>`;}if(page==='integrations')C.innerHTML+=`<div class="card auto-sync-card"><div class="row"><div><h2>Sinkronisasi kontak otomatis</h2><p class="muted">Kontak CRM aktif yang memiliki persetujuan ditambahkan otomatis ke list tujuan.</p></div>${btn('Atur list & otomatisasi','auto-sync','primary')}</div><p>${badge(S.config.auto_sync?'Aktif':'Dijeda')} ${S.config.default_list?'List tujuan ID '+S.config.default_list:'Belum ada list tujuan'}</p><p class="muted small">Webhooks Mailketing → CRM tetap memerlukan pemasangan URL di Mailketing. Kontak lama dibawa lewat CSV.</p></div>`;wire();if(page==='syncstatus')loadSync();if(page==='reports')loadReport();}
function refreshSelection(){const boxes=[...document.querySelectorAll('[data-contact-select]')],header=document.querySelector('#select-page');if(!header)return;const count=boxes.filter(b=>selectedContacts.has(b.dataset.contactSelect)).length;header.checked=boxes.length>0&&count===boxes.length;header.indeterminate=count>0&&count<boxes.length;header.disabled=!boxes.length;document.querySelector('#selection-count').textContent=num(selectedContacts.size)+' kontak dipilih';document.querySelector('[data-act="bulk-delete"]').disabled=!selectedContacts.size;}
