function open(title,html,submit,label='Simpan'){modal.innerHTML=`<form id="editor"><div class="row"><h2>${e(title)}</h2><button type="button" id="close">✕</button></div>${html}<div id="form-error" class="notice" style="display:none"></div><div class="footer"><button type="button" id="dismiss">${submit?'Batal':'Tutup'}</button>${submit?`<button class="primary">${e(label)}</button>`:''}</div></form>`;if(!modal.open)modal.showModal();document.querySelector('#close').onclick=document.querySelector('#dismiss').onclick=()=>modal.close();modal.querySelectorAll('input,select,textarea').forEach((el,i)=>{if(!el.id)el.id='dialog-field-'+i;const label=el.previousElementSibling;if(label?.tagName==='LABEL')label.htmlFor=el.id;});if(submit)document.querySelector('#editor').onsubmit=async ev=>{ev.preventDefault();const button=ev.submitter;button.disabled=true;try{const result=await submit(ev.target);modal.close();await load();toast(result?.message||'Tersimpan');}catch(err){const el=document.querySelector('#form-error');el.style.display='block';el.textContent=err.message;}finally{button.disabled=false;}};}
