 if(k==='templates')html+=`<div class="notice">Editor blok sederhana: judul, teks, gambar HTTPS, tombol, dan pembatas. HTML kustom tersedia di bawah.</div><div class="actions">${['heading','text','image','button','divider'].map(t=>`<button type="button" data-block="${t}">＋ ${t}</button>`).join('')}<button type="button" id="buildHTML">Blok → HTML</button></div><div id="blocks"></div><label>HTML email · merge tags: {{name}}, {{email}}, {{site_name}}, {{key_field}}</label><textarea name="html" id="html" style="min-height:200px">${e(d.html||'<h1>Halo {{name}}</h1><p>Selamat datang!</p>')}</textarea><div class="actions"><button type="button" id="previewHTML">Preview</button></div><iframe class="preview" id="emailPreview" sandbox=""></iframe>`;
